/// Exibe o caminho de forma amigável no rótulo de informações.
/// Caminhos longos são truncados com elipses nas duas pontas.
fn rotulo_caminho(caminho: &str, max: usize) -> String {
    let mut texto = caminho.to_string();
    if texto.is_empty() {
        return "· Nenhum arquivo ·".to_string();
    }
    if texto.len() <= max {
        return texto;
    }
    const OVERHEAD = 7; // "…" à esquerda + quebra de linha + "…" à direita
    const MEIO_MAX = max.saturating_sub(OVERHEAD);
    let livre = MEIO_MAX.min(texto.len() - OVERHEAD);
    let inicio = (texto.len() - livre).saturating_div(2);
    let miolo = &texto[inicio..inicio + livre];
    format!("...{}\n...", miolo)
}

