    // Grade central da interface
    // ------------------------------------------------------------------
    let grade = Grid::builder()
        .orientation(Orientation::Vertical)
        .spacing(8)
        .row_spacing(8)
        .column_spacing(8)
        .margin_top(14)
        .margin_start(14)
        .margin_end(14)
        .margin_bottom(14)
        .build();

    // Faixa de título em destaque
    let titulo = Label::builder()
        .text("WhisperLRC")
        .custom_font(PangoFontDescriptor::from_size_point(20.0)
                         .weight(gobject::PangoWeight::BOLD))
        .foreground_color(AZUL)
        .halign(Alignment::Center)
        .valign(Valignment::TOP)
        .padding_bottom(6)
        .padding_left(16)
        .padding_right(16)
        .build();

    // ---------------------------------------------------------------
    // 1) Entrada do arquivo + rótulo com informação resumida
    // ---------------------------------------------------------------
    let caixa_caminho = Rc::new(RefCell::new(entry.clone()));
    let rotulo_informacao = Rc::new(RefCell::new(Label::new(Some(
        "· Nenhum arquivo selecionado ·"
    ))));

    grade.attach(&*rotulo_informacao.borrow(), 0, 0, 5, 1);

    let entrada = Entry::builder()
        .halign(Alignment::Start)
        .valign(Valignment::TOP)
        .min_height(46)
        .placeholder_text("Arraste ou selecione um arquivo de áudio (MP3 / WAV / FLAC)")
        .padding_left(10)
        .padding_right(10)
        .padding_top(4)
        .padding_bottom(4)
        .build();

