    let busca = SearchEntry::builder()
        .halign(Align::End)
        .valign(Valignment::MIDDLE)
        .min_height(46)
        .placeholder_text("Buscar arquivo…")
        .width_reactive(true)
        .build();
    let clone_busca = busca.clone();
    busca.connect_clicked(move |_arquivo: PathBuf, _controle: &mut Widget| {
        if let Some(pick) = openfiledialog_box() {
            *caixa_caminho.borrow_mut().set_text(pick.to_str().unwrap_or(""));
        }
    });

    let botoao_paste = Button::builder()
        .label("Paste")
        .halign(Align::End)
        .valign(Valignment::MIDDLE)
        .min_height(46)
        .build();

    // Faixa horizontal: arquivo | paste | busca
    grade.attach(&entrada, 0, 1, 3, 1);
    grade.attach(&botoao_paste, 3, 1, 1, 1);
    grade.attach(&busca, 4, 1, 1, 1);

    let rotulo_clone = Rc::clone(&rotulo_informacao);
    let caixa_clone = caixa_caminho.clone();
