    // ---------------------------------------------------------------
    const MODELOS_VALIDOS: &[&str] = &["tiny", "turbo", "base", "small", "medium", "large"];

    let caixa_modelo = ComboBoxText::builder()
        .halign(Alignment::Start)
        .valign(Valignment::MIDDLE)
        .min_height(46)
        .build();
    for (indice, &modelo) in MODELOS_VALIDOS.iter().enumerate() {
        caixa_modelo.append_text(modelo);
    }
    // Mantém o modelo padrão ativado ("turbo", 2º item da lista)
    if let Some(i) = MODELOS_VALIDOS.iter().position(|&m| m == "turbo") {
        caixa_modelo.set_active(Some(i as u32));
    }

    let checagem = CheckButton::builder()
        .checked(false)
        .with_label("2º plano?")
        .halign(Align::End)
        .valign(Valignment::MIDDLE)
        .min_height(46)
        .build();

    // Rótulo + combinado + checagem, lado a lado
    let fila_modelo = Row::builder()
        .spacing(14)
        .valign(Valignment::MIDDLE)
        .build();

    let rotulo_modelo = Label::builder()
        .label("Modelo do Whisper: ")
        .halign(Align::End)
        .valign(Valignment::MIDDLE)
        .custom_font(PangoFontDescriptor::from_size_point(11.0)
                              .weight(gobject::PangoWeight::BOLD))
        .padding_left(10)
        .build();

    let filhos_modelo = vec![
        rotulo_modelo.box_view(),
        caixa_modelo.box_view(),
        checagem.box_view(),
    ];
    fila_modelo.append_all(&filhos_modelo);
    grade.attach(&fila_modelo, 0, 2, 5, 1);

    // ---------------------------------------------------------------
    // 3) Botões "Salvar" e "Executar"
    // ---------------------------------------------------------------
    let btn_salvar = Button::builder()
        .label("Salvar")
        .halign(Alignment::Start)
        .valign(Valignment::MIDDLE)
        .min_height(46)
        .tipovertext("Salva o progresso atual da geração da legenda")
        .build();

    let btn_executar = Button::builder()
        .label("Executar")
        .halign(Align::End)
        .valign(Valignment::MIDDLE)
        .min_height(46)
        .tipovertext("Gera a legenda LRC (SRT) a partir do áudio selecionado")
        .build();

    let fila_acoes = Row::builder()
        .spacing(20)
        .valign(Valignment::MIDDLE)
        .build();

    let filhos_acoes = vec![
        btn_salvar.box_view(),
        btn_executar.box_view(),
    ];
    fila_acoes.append_all(&filhos_acoes);
    grade.attach(&fila_acoes, 0, 3, 5, 1);

    // ------------------------------------------------------------------
    // Janela principal
    // ------------------------------------------------------------------
    let corpo_principal = Box::builder()
        .orientation(Orientation::Vertical)
        .spacing(14)
        .valign(Valignment::TOP)
        .build();

    corpo_principal.add(&titulo);
    corpo_principal.add(&grade);

